\begin{equation*}
\frac{1}{(7+x)}=\frac{\frac{1}{7}}{\frac{1}{7}(7+x)}=\frac{\frac{1}{7}}{1+\frac{1}{7}x}=\frac{1}{7}\cdot \frac{1}{1+\frac{1}{7}x}
\end{equation*}

\begin{equation*}
\frac{1}{(7+x)}=\frac{1}{7}\cdot \frac{1}{1+\frac{1}{7}x}=\frac{1}{7}\sum_{n=0}^{\infty}\left(\frac{-1}{7}x\right)^n=\frac{1}{7}\sum_{n=0}^{\infty}\left(\frac{-1}{7}\right)^nx^n
\end{equation*}

\begin{equation*}
\frac{1}{(7+x)}=\sum_{n=0}^{\infty}\frac{(-1)^n}{7^{n+1}}x^n
\end{equation*}

\begin{equation*}
f(x) = \frac{1}{(7+x)^2}
\end{equation*}

\begin{equation*}
g(x) = \frac{1}{(7+x)^3}
\end{equation*}

\begin{equation*}
h(x) = \frac{x^2}{(7+x)^3}
\end{equation*}

